//! Writes `target/mock_expected.json`: the results `tests/mockhost/mockhost.c` must reproduce
//! through the plugin ABI (plan §9.2). The dataset is generated by integer formulas that
//! `mockhost.c` mirrors exactly (`mock_data` below ⇔ `make_data` there).
//!
//! Usage: `cargo run --release -p fereg-core --example mock_expected [output.json]`

use fereg_core::{
    AbsorbTerm, AbsorberKind, Ctx, FactorValues, Family, Layout, Prep, Session, Spec, Vce, WeightKind,
};

const N: usize = 1000;

fn h(i: u64, k: u64) -> i64 {
    (((i * 2_654_435_761 + k * 40_503) % 4_294_967_296) % 2001) as i64 - 1000
}

struct MockData {
    fe1: Vec<f64>,
    fe2_bytes: Vec<u8>,
    fe2_off: Vec<u32>,
    y: Vec<f64>,
    x1: Vec<f64>,
    x2: Vec<f64>,
}

/// Observations 990..999 have unique fe1 levels (10 singletons).
fn mock_data() -> MockData {
    let mut d = MockData {
        fe1: Vec::new(),
        fe2_bytes: Vec::new(),
        fe2_off: vec![0],
        y: Vec::new(),
        x1: Vec::new(),
        x2: Vec::new(),
    };
    for i in 0..N as u64 {
        d.fe1.push(if i < 990 { (1 + (i * 7) % 50) as f64 } else { (1000 + i) as f64 });
        d.fe2_bytes.extend_from_slice(format!("g{:02}", (i * 13 + i / 7) % 20).as_bytes());
        d.fe2_off.push(d.fe2_bytes.len() as u32);
        d.x1.push(h(i, 1) as f64 / 100.0);
        d.x2.push(h(i, 2) as f64 / 100.0);
        d.y.push((h(i, 3) + 2 * h(i, 1) - h(i, 2)) as f64 / 100.0);
    }
    d
}

fn json_num(v: f64) -> String {
    if v.is_finite() { format!("{v:?}") } else { "null".into() }
}

fn json_arr(v: &[f64]) -> String {
    format!("[{}]", v.iter().map(|x| json_num(*x)).collect::<Vec<_>>().join(","))
}

fn main() {
    let out = std::env::args().nth(1).unwrap_or_else(|| {
        concat!(env!("CARGO_MANIFEST_DIR"), "/../../target/mock_expected.json").to_string()
    });
    let d = mock_data();
    let ctx = Ctx::quiet(1);
    let prep = Prep {
        n: N,
        factors: vec![FactorValues::Num(&d.fe1), FactorValues::Str { bytes: &d.fe2_bytes, offsets: &d.fe2_off }],
        absorb: vec![
            AbsorbTerm { factors: vec![0], intercept: true, slopes: vec![], save: false },
            AbsorbTerm { factors: vec![1], intercept: true, slopes: vec![], save: false },
        ],
        slope_vars: vec![],
        weights: None,
        weight_kind: WeightKind::None,
        vce: Vce::Unadjusted,
        drop_singletons: true,
        family: Family::Gaussian,
        y_for_sep: None,
        sep_fe: false,
    };
    let mut s = Session::prepare_with(prep, &ctx, AbsorberKind::Dense).expect("prepare (dense)");
    let dropped: Vec<f64> =
        s.keep().iter().enumerate().filter(|(_, k)| !**k).map(|(i, _)| i as f64).collect();
    let kept = |v: &[f64]| -> Vec<f64> { s.kept_index().iter().map(|&i| v[i as usize]).collect() };
    let (y, x1, x2) = (kept(&d.y), kept(&d.x1), kept(&d.x2));
    let rows = s.gather(&[&y, &x1, &x2], &ctx).expect("gather");
    let spec = Spec { tol: 1e-14, want_resid: true, ..Spec::default() };
    let n = s.n();
    let singletons = s.num_singletons();
    let (b, v, resid, status) = match s.ols(rows, &Layout::ols(2), &spec, &ctx) {
        Ok(r) => {
            let b = r.matrix("b").expect("b");
            let v = r.matrix("V").expect("V");
            (json_arr(&b.data), json_arr(&v.data), r.resid.as_deref().map_or("null".into(), json_arr), "\"ok\"".into())
        }
        Err(e) => ("null".into(), "null".into(), "null".into(), format!("\"pending: {}\"", e.to_string().replace('"', "'"))),
    };
    let json = format!(
        "{{\n\"n_input\": {N},\n\"N\": {n},\n\"num_singletons\": {singletons},\n\"dropped\": {},\n\"ols\": {status},\n\"b\": {b},\n\"V\": {v},\n\"resid\": {resid}\n}}\n",
        json_arr(&dropped)
    );
    std::fs::write(&out, json).expect("write expected json");
    println!("wrote {out}");
}
